(4659198, 672099, 67152, '<td valign="top">simple, storytelling, quiet, thoughtful, sad, perfect</td>', 'simple, storytelling, quiet, thoughtful, sad, perfect', '2008-04-25 14:14:26.000000', NULL, 1),
(4659200, 672011, 67152, '<td valign="top">these guys are great!  the brightness of the colors and the background work really well together.  i just think you would have an even more obvious connection to the challenge if you used three chili peppers</td>', 'these guys are great!  the brightness of the colors and the background work really well together.  i just think you would have an even more obvious connection to the challenge if you used three chili peppers', '2008-04-25 14:15:24.000000', NULL, 1),
